package com.kwl360.stickermaker;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity {
 LinearLayout root;String selected;static final int PICK=55;
 @Override public void onCreate(Bundle b){super.onCreate(b);render();}
 TextView label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(15,23,42));v.setPadding(6,14,6,14);return v;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void render(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,25,22,25);root.setBackgroundColor(Color.rgb(248,250,252));scroll.addView(root);setContentView(scroll);
 root.addView(label("🇵🇸 صانع ملصقات KWL",26));root.addView(label("أنشئ حزمًا متعددة، وارفع صورًا جديدة في أي وقت دون إعادة تثبيت التطبيق. كل حزمة تضم 3–30 ملصقًا ثابتًا.",16));
 root.addView(button("➕ إنشاء حزمة جديدة",()->{EditText t=new EditText(this);t.setHint("مثال: ملصقات الحب");new AlertDialog.Builder(this).setTitle("اسم الحزمة").setView(t).setPositiveButton("إنشاء",(d,w)->{try{String input=t.getText().toString().trim();final String name=input.isEmpty()?"ملصقاتي":input;new AlertDialog.Builder(this).setTitle("نوع الحزمة").setItems(new String[]{"ثابتة (PNG / JPG / WebP)","متحركة (WebP متحرك 512×512)"},(dialog,which)->{try{selected=PackStore.create(this,name,which==1);render();}catch(Exception ex){error(ex.getMessage());}}).show();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("إلغاء",null).show();}));
 JSONArray a=PackStore.packs(this);for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;String id=p.optString("id");int n=PackStore.count(this,id);root.addView(label("📦 "+p.optString("name")+(p.optBoolean("animated")?" 🎞️ متحركة":" 🖼️ ثابتة")+" — "+n+"/30 ملصق",20));root.addView(button("📷 إضافة صور لهذه الحزمة",()->{selected=id;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType(PackStore.get(this,id).optBoolean("animated")?"image/webp":"image/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,PICK);}));root.addView(button("✅ إضافة الحزمة إلى واتساب",()->install(id,"com.whatsapp")));root.addView(button("واتساب الأعمال",()->install(id,"com.whatsapp.w4b")));root.addView(button("🗑 حذف الحزمة",()->new AlertDialog.Builder(this).setMessage("حذف الحزمة وصورها؟").setPositiveButton("حذف",(d,w)->{PackStore.delete(this,id);render();}).setNegativeButton("إلغاء",null).show()));}
 root.addView(label("الحزم المتحركة تقبل ملفات WebP متحركة مجهزة مسبقًا بمقاس 512×512 وأقل من 500 كيلوبايت. GIF لا يُحوّل إلى متحرك داخل التطبيق حاليًا.",14));}
 void install(String id,String pkg){int n=PackStore.count(this,id);if(n<3){error("أضف 3 ملصقات على الأقل قبل التثبيت");return;}Intent intent=new Intent("com.whatsapp.intent.action.ENABLE_STICKER_PACK");intent.putExtra("sticker_pack_id",id);intent.putExtra("sticker_pack_authority",PackStore.AUTH);intent.putExtra("sticker_pack_name",PackStore.get(this,id).optString("name"));intent.setPackage(pkg);try{startActivityForResult(intent,200);}catch(Exception e){error("تعذر فتح واتساب. تحقق من تثبيته.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&result==RESULT_OK&&data!=null){int ok=0;String err="";try{if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++){try{PackStore.add(this,selected,data.getClipData().getItemAt(i).getUri());ok++;}catch(Exception e){err=e.getMessage();break;}}}else if(data.getData()!=null){PackStore.add(this,selected,data.getData());ok++;}}catch(Exception e){err=e.getMessage();}render();Toast.makeText(this,"تمت إضافة "+ok+" ملصقات"+(err.isEmpty()?"":" — "+err),Toast.LENGTH_LONG).show();}}
 void error(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("حسنًا",null).show();}
}